  `username` varchar(50) NOT NULL,
  `email` varchar(255) NOT NULL,
  `password` varchar(255) NOT NULL,
  `firstName` varchar(100) NOT NULL,
  `lastName` varchar(100) NOT NULL,
  `role` enum('admin','nurse','supervisor','pharmacy') NOT NULL DEFAULT 'nurse',
  `verificationCode` varchar(6) NOT NULL,
  `verificationCodeExpires` datetime NOT NULL,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `phone` varchar(30) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UQ_19605d7fa35cb33d0277a1966fd` (`username`),
  UNIQUE KEY `UQ_ee0dba4c34b22d1bce194e75ab3` (`email`),
  KEY `IDX_PENDING_REG_EXPIRES` (`verificationCodeExpires`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
