--
-- Table structure for table `schedules`
--

DROP TABLE IF EXISTS `schedules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `schedules` (
  `id` int NOT NULL AUTO_INCREMENT,
  `patientId` int NOT NULL,
  `assignedToId` int DEFAULT NULL,
  `type` enum('medication','check','treatment','other') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'other',
  `status` enum('pending','completed','missed','cancelled') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `scheduledTime` datetime NOT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `medication` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `dosage` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `IDX_SCHEDULE_PATIENT_ID` (`patientId`),
  KEY `IDX_SCHEDULE_SCHEDULED_TIME` (`scheduledTime`),
  KEY `IDX_SCHEDULE_STATUS` (`status`),
  KEY `IDX_SCHEDULE_PATIENT_STATUS` (`patientId`,`status`),
  KEY `IDX_SCHEDULE_PATIENT_TIME` (`patientId`,`scheduledTime`),
  KEY `IDX_SCHEDULE_ASSIGNED_TO` (`assignedToId`),
  KEY `IDX_SCHEDULE_TYPE_STATUS` (`type`,`status`),
  CONSTRAINT `FK_3b662d86d93c5febacaf65417d6` FOREIGN KEY (`patientId`) REFERENCES `patients` (`id`),
  CONSTRAINT `FK_f2a6ccc2f5105c830785bfbc15a` FOREIGN KEY (`assignedToId`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2203 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

