DROP TABLE IF EXISTS `shift_attendance`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `shift_attendance` (
  `id` int NOT NULL AUTO_INCREMENT,
  `date` date NOT NULL,
  `shiftId` int NOT NULL,
  `nurseId` int NOT NULL,
  `status` enum('present','absent','late','justified','missing') NOT NULL DEFAULT 'absent',
  `checkInAt` datetime DEFAULT NULL,
  `checkOutAt` datetime DEFAULT NULL,
  `recordedBy` int DEFAULT NULL,
  `notes` varchar(500) DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UQ_shift_attendance_date_shift_nurse` (`date`,`shiftId`,`nurseId`),
  KEY `FK_aad9304ab8e6894e3b8ee914b4c` (`shiftId`),
  KEY `FK_992af6634ba73a91e5f8ea2cab1` (`nurseId`),
  KEY `FK_b38b384c527d2f628f1f08674cb` (`recordedBy`),
  KEY `IDX_shift_attendance_date_shift` (`date`,`shiftId`),
  CONSTRAINT `FK_992af6634ba73a91e5f8ea2cab1` FOREIGN KEY (`nurseId`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `FK_aad9304ab8e6894e3b8ee914b4c` FOREIGN KEY (`shiftId`) REFERENCES `shifts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `FK_b38b384c527d2f628f1f08674cb` FOREIGN KEY (`recordedBy`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

